    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        int n = input.nextInt();
        String s = input.next();
        char[] arr = s.toCharArray();
        int[] countsArr = new int[n];
        int totalWordsCount = 0;
        int currentIndex = 0;
        for (int i = 0; i < n; i++) {
            countsArr[i] = 0;
        }
        int modeState = 0;
        if (arr[0] == '_') {
            modeState = 0;
        } else if (arr[0] == '(') {
            modeState = 1;
        }
        for (int i = 0; i < n; i++) {
            if (modeState == 0) {
                if (arr[i] == '_') {
                    currentIndex++;
                } else {
                    if (arr[i] != '(') {
                        countsArr[currentIndex]++;
                    } else if (arr[i] == '(') {
                        modeState = 1;
                    } else if (arr[i] == ')') {
                        modeState = 0;
                    }
                }
            } else {
                if (arr[i] == ')') {
                    modeState = 0;
                    currentIndex++;
                } else if (i > 0) {
                    if (arr[i - 1] == '(' || arr[i - 1] == '_') {
                        if (arr[i] != '_' && arr[i] != '(') {
                            totalWordsCount++;
                        }
                    }
                }
            }
        }
        // Bubble sort in descending order
        for (int i = 0; i < n; i++) {
            for (int j = i; j > 0; j--) {
                if (countsArr[j] > countsArr[j - 1]) {
